 const [session,setSession]=useState(null); const [authLoading,setAuthLoading]=useState(true); const [dataLoading,setDataLoading]=useState(false);
 const [page,setPage]=useState('Dashboard'); const [mobileMenuOpen,setMobileMenuOpen]=useState(false); const [rows,setRows]=useState([]); const [categories,setCategories]=useState([]); const [settings,setSettings]=useState(null); const [query,setQuery]=useState(''); const [selected,setSelected]=useState(null); const [controle,setControle]=useState(null); const [controles,setControles]=useState([]); const [members,setMembers]=useState([]); const [organizations,setOrganizations]=useState([]); const [organization,setOrganization]=useState(null); const [orgMembers,setOrgMembers]=useState([]); const [budgets,setBudgets]=useState([]); const [recurrences,setRecurrences]=useState([]); const [splits,setSplits]=useState([]); const [notice,setNotice]=useState('');
 useEffect(()=>{supabase.auth.getSession().then(({data})=>{setSession(data.session);setAuthLoading(false)}); const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s)); return()=>subscription.unsubscribe()},[]);
 useEffect(()=>{if(session?.user) loadData(); else {setRows([]);setControle(null);setControles([]);setOrganization(null);setOrganizations([])}},[session?.user?.id]);
 async function loadData(preferredControlId=null,preferredOrgId=null){setDataLoading(true);await supabase.rpc('aceitar_meus_convites_org');await supabase.rpc('aceitar_meus_convites');let {data:orgs,error:orgError}=await supabase.from('organizacoes').select('*').eq('ativo',true).order('created_at');if(orgError){setNotice('Organizações: '+orgError.message);setDataLoading(false);return}if(!orgs||orgs.length===0){const r=await supabase.from('organizacoes').insert({owner_id:session.user.id,nome:'Minha organização',email:session.user.email,cor_primaria:'#0877f9'}).select().single();if(r.error){setNotice(r.error.message);setDataLoading(false);return}orgs=[r.data]}setOrganizations(orgs);const wantedOrg=preferredOrgId||organization?.id;const org=orgs.find(x=>x.id===wantedOrg)||orgs[0];setOrganization(org);setSettings({...org,nome_empresa:org.nome,nome_exibicao:org.nome});const om=await supabase.from('organizacao_membros').select('*').eq('organizacao_id',org.id).order('created_at');setOrgMembers(om.data||[]);let {data:cs,error:controlsError}=await supabase.from('controles').select('*').eq('organizacao_id',org.id).eq('ativo',true).order('created_at');if(controlsError){setNotice('Controles: '+controlsError.message);setDataLoading(false);return}if(!cs||cs.length===0){const r=await supabase.from('controles').insert({user_id:session.user.id,organizacao_id:org.id,nome:'Meu controle'}).select().single();if(r.error){setNotice(r.error.message);setDataLoading(false);return}cs=[r.data]}setControles(cs);const wanted=preferredControlId||controle?.id;const c=cs.find(x=>x.id===wanted)||cs[0];setControle(c);let {data:catData,error:catError}=await supabase.from('categorias').select('*').eq('organizacao_id',org.id).order('nome');if(!catError&&(!catData||catData.length===0)&&org.owner_id===session.user.id){await supabase.from('categorias').insert(defaultCats.map((nome,i)=>({user_id:session.user.id,organizacao_id:org.id,nome,descricao:'Categoria inicial do ContaClaraAI',ativo:true,ordem:i})));const rr=await supabase.from('categorias').select('*').eq('organizacao_id',org.id).order('nome');catData=rr.data||[]}if(catError)setNotice('Categorias: '+catError.message);else setCategories(catData||[]);const {data,error}=await supabase.from('despesas').select('*').eq('controle_id',c.id).order('data',{ascending:false}).order('created_at',{ascending:false});if(error)setNotice(error.message);else setRows((data||[]).map(dbToRow));const mr=await supabase.from('controle_membros').select('*').eq('controle_id',c.id).order('created_at');setMembers(mr.data||[]);const [br,rr,sr]=await Promise.all([supabase.from('orcamentos').select('*').eq('controle_id',c.id).order('mes',{ascending:false}),supabase.from('despesas_recorrentes').select('*').eq('controle_id',c.id).order('created_at',{ascending:false}),supabase.from('rateios').select('*').eq('controle_id',c.id).order('created_at',{ascending:false})]);setBudgets(br.data||[]);setRecurrences(rr.data||[]);setSplits(sr.data||[]);setDataLoading(false)}
 async function switchOrganization(id){setSelected(null);setQuery('');setControle(null);await loadData(null,id);setPage('Dashboard')}
 async function createOrganization(form){const nome=form.nome?.trim();if(!nome)return false;const {data,error}=await supabase.from('organizacoes').insert({owner_id:session.user.id,nome,email:session.user.email,cor_primaria:'#0877f9'}).select().single();if(error){setNotice(error.message);return false}setNotice('Organização criada com sucesso.');await loadData(null,data.id);return true}
 async function inviteOrgMember(email,papel){if(!organization)return false;const normalized=email.trim().toLowerCase();const {error}=await supabase.from('organizacao_membros').upsert({organizacao_id:organization.id,email:normalized,papel,status:'pendente',convidado_por:session.user.id,updated_at:new Date().toISOString()},{onConflict:'organizacao_id,email'});if(error){setNotice(error.message);return false}setNotice('Convite da organização registrado.');await loadData(controle?.id,organization.id);return true}
 async function changeOrgMember(id,papel){const {error}=await supabase.from('organizacao_membros').update({papel,updated_at:new Date().toISOString()}).eq('id',id);if(error)setNotice(error.message);else await loadData(controle?.id,organization.id)}
 async function removeOrgMember(id){const {error}=await supabase.from('organizacao_membros').delete().eq('id',id);if(error)setNotice(error.message);else await loadData(controle?.id,organization.id)}
